import React, { useEffect, useState } from "react";
import styled from "styled-components";
import { useNavigate } from "react-router-dom";
import TabBar from "../../components/common/TabBar";
import BookingTile from "../../components/common/BookingTile";
import salonImage from "../../images/oliviaSalon.jpg"; // fallback
import api from "../../utils/api";

// ---- Styled Components ----
const PageWrapper = styled.div`
  background-color: #f2dcdc;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
`;

const ContentWrapper = styled.div`
  width: 100%;
  max-width: 1600px;
  padding: 40px 0;
  margin-left: 0;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 60px;
`;

const Section = styled.div`
  width: 100%;
`;

const SectionTitle = styled.h2`
  font-family: "Inter", sans-serif;
  font-size: 36px;
  font-weight: 800;
  color: #27374d;
  margin-bottom: 25px;
`;

const TilesContainer = styled.div`
  display: flex;
  flex-direction: column;
  gap: 25px;
`;

const EmptyText = styled.p`
  font-size: 15px;
  color: #555;
`;

const ErrorText = styled.p`
  font-size: 14px;
  color: red;
`;

// ---- Types ----
type BookingStatus = "pending" | "confirmed" | "cancelled" | "completed";

type BookingApi = {
  _id: string;
  business: {
    businessName: string;
    address?: string;
    city?: string;
    profileImageUrl?: string;
  };
  services: {
    name: string;
    durationMinutes: number;
    priceBHD: number;
  }[];
  startTime: string;
  status: BookingStatus;
  staffName?: string | null;
};

type BookingCard = {
  id: string;
  date: string;
  image: string;
  salonName: string;
  location: string;
  services: string[];
  status: BookingStatus;
};

const BookingsPage: React.FC = () => {
  const navigate = useNavigate();

  const [upcomingBookings, setUpcomingBookings] = useState<BookingCard[]>([]);
  const [pastBookings, setPastBookings] = useState<BookingCard[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const loadBookings = async () => {
      try {
        setLoading(true);
        setError(null);

        const res = await api.get<BookingApi[]>("/bookings/me");
        const data = res.data || [];

        const now = new Date();

        const upcoming: BookingCard[] = [];
        const past: BookingCard[] = [];

        data.forEach((b) => {
          const start = new Date(b.startTime);
          const isFuture = start.getTime() >= now.getTime();

          const dateStr = start.toLocaleString(undefined, {
            weekday: "short",
            month: "short",
            day: "numeric",
            hour: "numeric",
            minute: "2-digit",
          });

          const card: BookingCard = {
            id: b._id,
            date: dateStr,
            image: b.business?.profileImageUrl || salonImage,
            salonName: b.business?.businessName || "Unknown Salon",
            location: `${b.business?.city || ""}${
              b.business?.city && b.business?.address ? " · " : ""
            }${b.business?.address || ""}`,
            services: (b.services || []).map((s) => s.name),
            status: b.status,
          };

          if (
            isFuture &&
            b.status !== "cancelled" &&
            b.status !== "completed"
          ) {
            upcoming.push(card);
          } else {
            past.push(card);
          }
        });

        setUpcomingBookings(upcoming);
        setPastBookings(past);
      } catch (err: any) {
        console.error("Error loading bookings", err);
        setError(
          err?.response?.data?.message || "Failed to load bookings."
        );
      } finally {
        setLoading(false);
      }
    };

    loadBookings();
  }, []);

  return (
    <PageWrapper>
      <TabBar type="customer" />

      <ContentWrapper>
        <Section>
          <SectionTitle>Upcoming Bookings</SectionTitle>
          {loading && <EmptyText>Loading your bookings...</EmptyText>}
          {error && <ErrorText>{error}</ErrorText>}
          {!loading && !error && upcomingBookings.length === 0 && (
            <EmptyText>You have no upcoming bookings.</EmptyText>
          )}
          <TilesContainer>
            {upcomingBookings.map((booking) => (
              <BookingTile
                key={booking.id}
                {...booking}
                onCancel={() =>
                  alert(`Cancel booking ${booking.id} (hook up API)`)
                }
                onViewReceipt={() =>
                  navigate(`/bookings/${booking.id}`)
                }
                onReschedule={() =>
                  alert(`Reschedule booking ${booking.id}`)
                }
              />
            ))}
          </TilesContainer>
        </Section>

        <Section>
          <SectionTitle>Past Bookings</SectionTitle>
          {!loading && !error && pastBookings.length === 0 && (
            <EmptyText>You have no past bookings yet.</EmptyText>
          )}
          <TilesContainer>
            {pastBookings.map((booking) => (
              <BookingTile
                key={booking.id}
                {...booking}
                onLeaveRating={() =>
                  alert(`Leave rating for booking ${booking.id}`)
                }
                onViewReceipt={() =>
                  navigate(`/bookings/${booking.id}`)
                }
              />
            ))}
          </TilesContainer>
        </Section>
      </ContentWrapper>
    </PageWrapper>
  );
};

export default BookingsPage;
